CREATE TABLE routines (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), principal_id TEXT NOT NULL REFERENCES users(id), version INTEGER NOT NULL, enabled INTEGER NOT NULL, next_at TEXT, webhook_secret TEXT, event_cursor INTEGER NOT NULL DEFAULT 0, deleted INTEGER NOT NULL DEFAULT 0);
CREATE TABLE routine_versions (routine_id TEXT REFERENCES routines(id) ON DELETE CASCADE, version INTEGER NOT NULL, definition TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(routine_id,version));
CREATE TABLE routine_jobs (id TEXT PRIMARY KEY, routine_id TEXT NOT NULL REFERENCES routines(id), version INTEGER NOT NULL, occurrence TEXT NOT NULL, state TEXT NOT NULL, bot_id TEXT, run_id TEXT, handoffs TEXT, data TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, detail TEXT, UNIQUE(routine_id,version,occurrence));
CREATE TABLE webhook_deliveries (routine_id TEXT REFERENCES routines(id) ON DELETE CASCADE, delivery_id TEXT NOT NULL, digest TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(routine_id,delivery_id));
